import { normalize } from "./utils.js";
const metricName = (name, key) => `${name}_${normalize(key)}`.replace(/[^a-zA-Z0-9_:]/g, "_").replace(/^(\d)/, "_$1");
const labelName = (name) => name.replace(/[^a-zA-Z0-9_]/g, "_").replace(/^(\d)/, "_$1");
const escapeLabelValue = (value) => value.replace(/\\/g, "\\\\").replace(/\n/g, "\\n").replace(/"/g, '\\"');
export const renderLabels = (labels) => {
    if (typeof labels === "string") {
        return labels.trim() === "" ? "" : `{${labels}}`;
    }
    const entries = Object.entries(labels ?? {});
    if (entries.length === 0) {
        return "";
    }
    return `{${entries.map(([key, value]) => `${labelName(key)}="${escapeLabelValue(String(value))}"`).join(",")}}`;
};
export const renderPrometheus = (lines, labels) => {
    const renderedLabels = renderLabels(labels);
    const values = new Map();
    for (const { name, key, value } of lines) {
        const metric = metricName(name, key);
        values.set(metric, (values.get(metric) ?? 0) + value);
    }
    return [...values].map(([metric, value]) => `${metric}${renderedLabels} ${value}`).join("\n") + "\n";
};
export const labelsFromEnv = (env = process.env) => env.ALLURE_PROMETHEUS_LABELS ?? env["allure.prometheus.labels"];
